import type { VNodeChild } from '@pyreon/core'

export interface ButtonProps {
  /** Visible text. */
  label: string
  variant?: 'solid' | 'soft' | 'outline' | 'ghost'
  size?: 'sm' | 'md' | 'lg'
  onClick?: () => void
}

export function Button(props: ButtonProps): VNodeChild {
  return (
    <button class={`btn btn-${props.variant ?? 'solid'} btn-${props.size ?? 'md'}`} onClick={props.onClick}>
      {props.label}
    </button>
  )
}

