// atlas.config.ts: only the case a prop type cannot describe
import type { PlayContext } from '@pyreon/atlas/core'

let clicks = 0

export const scenarios = {
  Button: [
    {
      name: 'Submits once',
      args: { label: 'Save', onClick: () => { clicks++ } },
      play: async ({ root, step }: PlayContext) => {
        clicks = 0
        await step('click Save', () => {
          const button = root.querySelector('button')
          if (!button) throw new Error('no button rendered')
          button.click()
        })
        await step('onClick ran once', () => {
          if (clicks !== 1) throw new Error(`onClick ran ${clicks} times`)
        })
      },
    },
  ],
}
